import { Component } from '@angular/core';
import { FormControl } from '@angular/forms';
import { combineLatest, Observable, of, Subject } from 'rxjs';
import { map, switchMap } from 'rxjs/operators';
import { CountryService } from './country.service';
import { Country, State } from './types';

@Component({
  selector: 'app-solution3',
  templateUrl: './solution4.component.html',
  styleUrls: ['./solution4.component.css'],
})
export class Solution4Component {
  countries$: Observable<Country[]>;
  currentCountry$ = new Subject<Country>();
  states$: Observable<State[]>;
  statesForCountry$: Observable<State[]> = of([]);
  state: State;
  countryControl = new FormControl('');
  stateControl = new FormControl('');

  constructor(private service: CountryService) {
    this.countries$ = combineLatest([this.countryControl.valueChanges, this.service.getCountries()]).pipe(
      map(([userInput, countries]) =>
        countries.filter((c) => c.description.toLowerCase().indexOf(userInput.toLowerCase()) !== -1),
      ),
    );
    this.statesForCountry$ = this.currentCountry$
      .asObservable()
      .pipe(switchMap((cntry) => this.service.getStatesFor(cntry.id)));
    this.states$ = combineLatest([this.stateControl.valueChanges, this.statesForCountry$]).pipe(
      map(([userInput, states]) =>
        states.filter((c) => c.description.toLowerCase().indexOf(userInput.toLowerCase()) !== -1),
      ),
    );
  }

  updateStates(country: Country) {
    this.countryControl.setValue(country.description);
    this.stateControl.setValue('');
    this.currentCountry$.next(country);
  }
}
<h2>Solution 4</h2>
<h2>Result</h2>
<div>
  <div class="dropdown">
    <input type="text" class="dropbtn" [formControl]="countryControl" placeholder="Enter country name" />
    <div class="dropdown-content">
      <span
        *ngFor="let country of countries$ | async"
        (click)="updateStates(country)"
        [innerHTML]="country.description | highlight: countryControl.value"
      >
      </span>
    </div>
  </div>
</div>
<div>
  <div class="dropdown">
    <input type="text" class="dropbtn" [formControl]="stateControl" placeholder="Enter your state" />
    <div class="dropdown-content">
      <span
        *ngFor="let s of states$ | async"
        (click)="stateControl.setValue(s.description)"
        [innerHTML]="s.description | titlecase | highlight: stateControl.value"
      >
      </span>
    </div>
  </div>
</div>
